SET SESSION TRANSACTION ISOLATION LEVEL SERIALIZABLE; SET SESSION innodb_lock_wait_timeout=3; START TRANSACTION; SELECT balance INTO @first FROM Accounts WHERE account_id=9; SELECT CONCAT('FIRST|',@first); SELECT SLEEP(6); SELECT CONCAT('CHANGED|',IF(balance<>@first,'OBSERVED','NOT OBSERVED')) FROM Accounts WHERE account_id=9; COMMIT;